BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8741b9b4a20fa26f3204e3b49150ae61ad62ec9b/content/books/zizhi-tongjian/vol-292/year-0955/part-03/sources/library/jiuwudaishi-115-july-commanders/source.txt", "note": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002734；EPUB电子本，纸本及异文待核", "id": "51057c2a-696c-5eac-9f45-3c94823c5a19"}, {"title": "旧五代史·卷一百十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8741b9b4a20fa26f3204e3b49150ae61ad62ec9b/content/books/zizhi-tongjian/vol-292/year-0955/part-03/sources/library/jiuwudaishi-115-june-955/source.txt", "note": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002733；EPUB电子本，纸本及异文待核", "id": "d3e222b6-b4b3-5484-b0d1-9dfcb1f60cdc"}, {"title": "旧五代史·卷一百十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8741b9b4a20fa26f3204e3b49150ae61ad62ec9b/content/books/zizhi-tongjian/vol-292/year-0955/part-03/sources/library/jiuwudaishi-115-monk-registers/source.txt", "note": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002731；EPUB电子本，纸本及异文待核", "id": "ff64903e-32fa-5c7c-9e9e-54a75562bc2b"}, {"title": "旧五代史·卷一百十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8741b9b4a20fa26f3204e3b49150ae61ad62ec9b/content/books/zizhi-tongjian/vol-292/year-0955/part-03/sources/library/jiuwudaishi-115-temple-edict-date/source.txt", "note": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002728；EPUB电子本，纸本及异文待核", "id": "7eabd0e7-101c-523a-9c6c-1f5536a53440"}, {"title": "旧五代史·卷一百十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8741b9b4a20fa26f3204e3b49150ae61ad62ec9b/content/books/zizhi-tongjian/vol-292/year-0955/part-03/sources/library/jiuwudaishi-115-temple-rationale/source.txt", "note": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002729；EPUB电子本，纸本及异文待核", "id": "2da1209c-584a-5a88-b944-11af0a3b33eb"}, {"title": "旧五代史·卷一百十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8741b9b4a20fa26f3204e3b49150ae61ad62ec9b/content/books/zizhi-tongjian/vol-292/year-0955/part-03/sources/library/jiuwudaishi-115-temple-regulations/source.txt", "note": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002730；EPUB电子本，纸本及异文待核", "id": "08451b3c-5485-5cb3-bc6a-4557956947bd"}, {"title": "旧五代史·卷一百十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8741b9b4a20fa26f3204e3b49150ae61ad62ec9b/content/books/zizhi-tongjian/vol-292/year-0955/part-03/sources/library/jiuwudaishi-115-temple-year-totals/source.txt", "note": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002732；EPUB电子本，纸本及异文待核", "id": "155ee8f8-213c-52b6-adf6-e9dbb9674dab"}, {"title": "旧五代史·卷一百十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8741b9b4a20fa26f3204e3b49150ae61ad62ec9b/content/books/zizhi-tongjian/vol-292/year-0955/part-03/sources/library/jiuwudaishi-115-zhangmei-eight-month/source.txt", "note": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002735；EPUB电子本，纸本及异文待核", "id": "17a4792f-88dd-5107-943a-14941d266127"}, {"title": "新五代史·卷六十四", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8741b9b4a20fa26f3204e3b49150ae61ad62ec9b/content/books/zizhi-tongjian/vol-292/year-0955/part-03/sources/library/xinwudaishi-64-zhao-jizha-return/source.txt", "note": "《新五代史》卷六十四，段落 xin-wudaishi-b08f244b9241-p003243；EPUB电子本，纸本及异文待核", "id": "8d8d1d42-cc51-5dc9-97dd-7d812c0357d5"}, {"title": "新五代史·卷六十五", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/8741b9b4a20fa26f3204e3b49150ae61ad62ec9b/content/books/zizhi-tongjian/vol-292/year-0955/part-03/sources/library/xinwudaishi-65-liuhongzheng-killed/source.txt", "note": "《新五代史》卷六十五，段落 xin-wudaishi-b08f244b9241-p003290；EPUB电子本，纸本及异文待核", "id": "1e18fae2-9ae3-5449-9bfe-ac303d10f0e4"}, {"title": "资治通鉴·后周纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6a163584ccc696d903a1d677cbce57a2328b297b/content/books/zizhi-tongjian/vol-292/year-0955/part-02/sources/library/tongjian-292-955-qinfeng-first-order/source.txt", "note": "《资治通鉴》后周纪三，段落 zizhi-tongjian-a63549944a71-p003469；电子底本待考，分段待核", "id": "b9e28c71-de1a-56b8-b958-f61e46078893"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "王景（后晋耀州团练使）", "aliases": ["王景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "掖县人，曾任相州刺史。范延光叛乱时，他拒绝服从范延光。938年任耀州团练使。生卒年未载。", "biography": null, "status": "draft", "id": "95c5e667-cc89-51aa-862e-471795aa6956"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "李廷珪", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀将领。947年十二月任奉銮肃卫都虞候，率二万兵出子午谷援长安。生卒年尚未录入。", "biography": null, "status": "draft", "id": "376820ae-41ca-57e0-b117-00976a8545fc"}, {"name": "高彦俦", "aliases": ["高彥儔"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：高彦俦，太原人、昭武都监、拟领兵者。", "biography": null, "status": "draft", "id": "b335c31e-ee43-595d-8eb5-e601824ba527"}, {"name": "吕彦珂", "aliases": ["呂彥珂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀武宁节度使。955年五月，孟昶安排他作为高彦俦的副手参加北路行营，抵御后周军。生卒年未载。", "biography": null, "status": "draft", "id": "0ba0ded7-c462-5a35-8df5-9a00d2f7e545"}, {"name": "赵崇韬", "aliases": ["趙崇韜"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀客省使。955年五月，孟昶任命他为北路行营都监，参与抵御后周军的部署。生卒年未载。", "biography": null, "status": "draft", "id": "ac2d7f68-da6e-560c-8f7c-7521a8bbffce"}, {"name": "赵季札", "aliases": ["趙季札"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀客省使。952年受孟昶之命赴梓州，慰抚吏民。生卒年未载。", "biography": null, "status": "draft", "id": "faffdaed-5d02-5666-a551-64c61d7f86a3"}, {"name": "马遇", "aliases": ["馬遇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "汝州民众。955年六月柴荣亲审囚犯时，查明马遇父亲和弟弟被官吏冤枉致死的情况。《通鉴》未记其家人姓名和后续处理细节。", "biography": null, "status": "draft", "id": "599fb8fa-cd95-5f48-be19-e7e624e7efda"}, {"name": "胡立", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周濮州刺史，955年六月西征时任排陈使，在威武城东与后蜀军交战失利后被俘。生卒年未载。", "biography": null, "status": "draft", "id": "28690c1d-310a-550c-a5e5-13d3b8f2377f"}, {"name": "刘承钧", "aliases": ["劉承鈞", "刘钧", "劉鈞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘崇的次子。951年父亲在晋阳称帝时，任侍卫亲军都指挥使、太原尹。《旧五代史》也记他是刘崇之子并任两职。生卒年本批未录。", "biography": null, "status": "draft", "id": "3f4681a7-ca79-5d5d-a5c2-53bef1936681"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "韩通", "aliases": ["韓通"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后周保义军留后。954年正月正式任保义节度使，《旧五代史》以陕州留后称其前职。生卒年暂未核定。", "biography": null, "status": "draft", "id": "81e4d74c-3057-59e4-a9a3-5baa18bff059"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙", "刘晟", "劉晟"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "刘弘政", "aliases": ["劉弘政", "刘洪政", "劉洪政"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘政，获封王爵之子。", "biography": null, "status": "draft", "id": "54e33c62-ec7b-5326-a97a-bb38906eed63"}, {"name": "张美", "aliases": ["張美"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "清河人，后周枢密院承旨。《通鉴》记955年六月任右领军大将军、权点检三司事，《旧五代史》记八月任权判三司，任职月与称号差异分别保留。早年管理澶州隶属三司的财物，曾应柴荣私人所求而供给，郭威得知后将他调到濮州。", "biography": null, "status": "draft", "id": "e0ae365f-4a51-5f92-82eb-86e617f0d42b"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "向训", "aliases": ["向訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周军官。951年与陈思让参与虒亭战事，《旧五代史》称监军，《宋史》称都监。生卒年及后续改名尚未据本次引文录入。", "biography": null, "status": "draft", "id": "1d29bcb9-6ec9-5369-89ff-ea67f0460acc"}, {"name": "赵匡胤", "aliases": ["趙匡胤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周宿卫将领，后来成为宋太祖。954年高平之战右军溃逃后，与张永德分率两翼反击北汉军。《宋史》本纪印证其率同列冲锋的记载。生卒年留待相应史料补录。", "biography": null, "status": "draft", "id": "ce0fe2a6-d446-50c7-b968-4245fd9693ad"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "柴荣下令停废没有敕额的寺院", "start_year": 955, "end_year": 955, "time_original": "955年五月，具体日据《旧五代史》记为甲戌", "dynasty": "五代十国", "description": "柴荣下令停废没有朝廷敕赐名额的寺院。《旧五代史》所载诏令还规定，将佛像和僧尼迁入保留的寺院；无敕额寺院的县城、军镇等另有留设例外，不能理解为所有寺院一律拆毁。", "phases": [], "location_name": "后周辖区", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b394f5cf-01d1-5d50-a6a0-f86a72868875"}, {"title": "柴荣禁止私度僧尼，并规定出家须获家人许可", "start_year": 955, "end_year": 955, "time_original": "955年五月寺院整顿诏令", "dynasty": "五代十国", "description": "柴荣禁止未经许可剃度僧尼，要求有意出家者先取得家人同意。《旧五代史》详记按父母祖父母、已孤者同居伯叔兄等情况处理，并设年龄、经文考核和奉养家人等条件。", "phases": [], "location_name": "后周辖区", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d7968416-545a-522d-ba33-47d3e780d04b"}, {"title": "柴荣限定两京等地可以设置戒坛", "start_year": 955, "end_year": 955, "time_original": "955年五月寺院整顿诏令", "dynasty": "五代十国", "description": "柴荣限定两京等地可以设置戒坛。", "phases": [], "location_name": "两京、大名府、京兆府、青州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "97f1daa7-05e2-58bb-9d16-a8e72e3da2e6"}, {"title": "柴荣禁止以毁伤身体等方式聚众惑众", "start_year": 955, "end_year": 955, "time_original": "955年五月寺院整顿诏令", "dynasty": "五代十国", "description": "柴荣禁止僧俗以舍身、断手足、炼指、挂灯、带钳等方式聚众惑众。这里记录诏令及其对这些行为的判断，未据此认定所有宗教活动都属欺骗。", "phases": [], "location_name": "后周辖区", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8f422b4b-d5b7-5be4-baf6-4fc78881ec30"}, {"title": "柴荣要求每年编造僧尼名册，及时登记死亡和还俗", "start_year": 955, "end_year": 955, "time_original": "955年五月诏令规定此后每年办理", "dynasty": "五代十国", "description": "柴荣要求每年编造僧尼名册，及时登记死亡和还俗。", "phases": [], "location_name": "两京及后周诸州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "922c5bed-ac75-5ddb-893e-65ee402c27ce"}, {"title": "《通鉴》统计955年保留和停废寺院及登记僧尼人数", "start_year": 955, "end_year": 955, "time_original": "955年全年汇总，统计截止日未载", "dynasty": "五代十国", "description": "《通鉴》记955年保留寺院2694所，停废30336所，登记僧人42444名、尼僧18756名。《旧五代史》记寺院两项数量相同，僧尼登记合计61200人。这些是史书记载的当年汇总，不是五月诏令颁布当天的实测数字。", "phases": [], "location_name": "后周辖区", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2cfc78fd-8324-5f03-8ea1-cf8d138a8768"}, {"title": "王景攻取黄牛等八座寨堡", "start_year": 955, "end_year": 955, "time_original": "955年五月戊寅部署之前，具体日未载", "dynasty": "五代十国", "description": "王景攻取黄牛等八座寨堡。", "phases": [], "location_name": "黄牛等八寨", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ecfc8849-759d-505d-b677-e9e0ab537cb7"}, {"title": "孟昶任李廷珪等四人统率北路行营", "start_year": 955, "end_year": 955, "time_original": "955年五月戊寅", "dynasty": "五代十国", "description": "孟昶任捧圣控鹤都指挥使、保宁节度使李廷珪为北路行营都统，左卫圣步军都指挥使高彦俦为招讨使，武宁节度使吕彦珂为副手，客省使赵崇韬为都监。", "phases": [], "location_name": "后蜀北路行营", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e95950cc-c7df-5fe7-84aa-cde947a04a0e"}, {"title": "赵季札到德阳后畏惧周军，请求解除边任并安排家属财物西归", "start_year": 955, "end_year": 955, "time_original": "955年五月丁亥回成都之前", "dynasty": "五代十国", "description": "赵季札到德阳，听说后周军入境后不敢继续前行。他上书请求解除边任、回朝奏事，并先送辎重及妓妾向西返回。此处没有记载赵季札曾抵达秦州。", "phases": [], "location_name": "德阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "4941bfab-f273-588e-8635-8b0648915af4"}, {"title": "赵季札独自骑马回成都，民众误以为军队战败而惊恐", "start_year": 955, "end_year": 955, "time_original": "955年五月丁亥", "dynasty": "五代十国", "description": "赵季札独自骑马回成都，民众误以为军队战败而惊恐。", "phases": [], "location_name": "成都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2e35d569-e5f0-5619-aa06-45e4bb4142a2"}, {"title": "孟昶问赵季札军情，因他不能回答而将其拘押", "start_year": 955, "end_year": 955, "time_original": "955年五月丁亥回成都之后、甲午处死之前", "dynasty": "五代十国", "description": "孟昶问赵季札军情，因他不能回答而将其拘押。", "phases": [], "location_name": "成都御史台", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "cdf888e7-c869-5b4f-86b9-ba4c890b67a0"}, {"title": "孟昶在崇礼门处死赵季札", "start_year": 955, "end_year": 955, "time_original": "955年五月甲午", "dynasty": "五代十国", "description": "孟昶在崇礼门处死赵季札。", "phases": [], "location_name": "成都崇礼门", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "830e2b49-4cf3-5606-8baa-35d7fff82103"}, {"title": "柴荣在内苑亲自审查囚犯", "start_year": 955, "end_year": 955, "time_original": "955年六月庚子", "dynasty": "五代十国", "description": "柴荣在内苑亲自审查囚犯。", "phases": [], "location_name": "后周内苑", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e8e2d9e3-c84e-58d5-9848-3eeb444632d7"}, {"title": "柴荣审查马遇一案，查明其父亲和弟弟被官吏冤枉致死", "start_year": 955, "end_year": 955, "time_original": "955年六月庚子查明；此前冤死和复查的具体时间未载", "dynasty": "五代十国", "description": "汝州民众马遇的父亲和弟弟被官吏冤枉致死，多次复查仍未能申冤。柴荣亲自询问才查明情况。史书未记涉案官吏、亲属姓名和后续赔偿处罚细节。", "phases": [], "location_name": "后周内苑，案涉汝州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b7be198c-d630-5446-a876-e90240f06849"}, {"title": "《通鉴》记马遇案后，各地方长官亲自察看诉讼", "start_year": 955, "end_year": 955, "time_original": "955年六月庚子马遇案之后，具体日未载", "dynasty": "五代十国", "description": "《通鉴》记柴荣查明马遇案后，人们赞叹其判断，各地长官也因此亲自察看诉讼。这里保留史书对影响的概述，不推成所有案件此后都已无冤错。", "phases": [], "location_name": "后周地方官府", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "79a8a70e-9fd5-5b8b-b903-21ab88b32916"}, {"title": "后周军在威武城东失利，胡立等人被后蜀军俘获", "start_year": 955, "end_year": 955, "time_original": "955年六月壬寅", "dynasty": "五代十国", "description": "后周军在威武城东失利，胡立等人被后蜀军俘获。", "phases": [], "location_name": "威武城东", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "911d4539-f3a0-56eb-bef8-d007fa1352d3"}, {"title": "孟昶派秘密使者联络北汉和南唐，提议共同出兵牵制后周", "start_year": 955, "end_year": 955, "time_original": "955年六月丁未派使", "dynasty": "五代十国", "description": "孟昶派秘密使者联络北汉和南唐，提议共同出兵牵制后周。", "phases": [], "location_name": "后蜀至北汉、南唐", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "555bdaf7-189d-537e-9000-23b7cd7fe3a4"}, {"title": "刘承钧和李璟同意孟昶提出的联合出兵计划", "start_year": 955, "end_year": 955, "time_original": "955年六月丁未派使之后，答复具体日未载", "dynasty": "五代十国", "description": "孟昶遣使邀请北汉、南唐共同出兵制约后周，刘承钧、李璟都答应。这是接受计划的记载，本段没有证明两国已经在丁未当天出兵。", "phases": [], "location_name": "北汉和南唐朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "3f860c46-2277-5e8d-b3c8-69292ab43a83"}, {"title": "柴荣任韩通为西南行营马步军都虞候", "start_year": 955, "end_year": 955, "time_original": "955年六月己酉", "dynasty": "五代十国", "description": "柴荣任韩通为西南行营马步军都虞候。", "phases": [], "location_name": "后周西南行营", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "dd318b88-412a-5ff2-a7d5-cdfcf3f4657c"}, {"title": "刘弘熙杀死通王刘弘政", "start_year": 955, "end_year": 955, "time_original": "955年六月戊午", "dynasty": "五代十国", "description": "南汉君主刘弘熙杀死祯州节度使、通王刘弘政。《通鉴》随后概述刘岩的其他儿子至此均已被杀；这句话不表示正在位的刘弘熙本人也已去世。", "phases": [], "location_name": "南汉", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b44b5d65-5e4d-51fd-a8ea-08f1c5ed331c"}, {"title": "柴荣任张美为右领军大将军，暂掌三司事务", "start_year": 955, "end_year": 955, "time_original": "《通鉴》记955年六月壬戌；《旧五代史》记八月丁未权判三司", "dynasty": "五代十国", "description": "柴荣任张美为右领军大将军，暂掌三司事务。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "7a763d84-d1df-51aa-a80f-8fe556b0692e"}, {"title": "张美在澶州管理财物时，曾应柴荣私人所求供给", "start_year": null, "end_year": null, "time_original": "柴荣在澶州期间的追述，具体年份和日期未载", "dynasty": "五代十国", "description": "张美在澶州管理财物时，曾应柴荣私人所求供给。", "phases": [], "location_name": "澶州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "fcfba7d7-00ae-58eb-a975-429949d84b35"}, {"title": "郭威得知张美向柴荣私人供给后，将张美调到濮州", "start_year": null, "end_year": null, "time_original": "郭威在位期间、张美澶州供给之后，具体年日未载", "dynasty": "五代十国", "description": "郭威得知张美为柴荣私人供给财物后发怒，但顾虑伤及柴荣的心意，只将张美调为濮州马步都虞候。这里的太祖是后周郭威，不能与同段后文所称宋太祖赵匡胤混同。", "phases": [], "location_name": "澶州至濮州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9f36359b-0cab-5ac4-867f-05a7053184d2"}, {"title": "柴荣任王景为西南行营都招讨使、向训为兵马都监", "start_year": 955, "end_year": 955, "time_original": "955年七月丁卯朔", "dynasty": "五代十国", "description": "柴荣任王景为西南行营都招讨使、向训为兵马都监。", "phases": [], "location_name": "后周西南行营", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f5dd5585-8ca2-5c24-adfb-1de9e4ed1960"}, {"title": "宰相因秦凤战事久无功、粮运不继，请求撤兵", "start_year": 955, "end_year": 955, "time_original": "955年七月行营任命以后，具体日未载", "dynasty": "五代十国", "description": "宰相因秦凤战事久无功、粮运不继，请求撤兵。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "3e3b7604-ef70-5a76-9250-b131b45a3d18"}, {"title": "柴荣派赵匡胤察看秦凤战局，听取可继续进取的报告", "start_year": 955, "end_year": 955, "time_original": "955年七月撤兵讨论之后，具体往返日未载", "dynasty": "五代十国", "description": "柴荣派赵匡胤到秦凤军前察看战局。赵匡胤回来后报告秦、凤可以攻取，柴荣听从其意见，继续推进战事。此处太祖皇帝是史书对后来宋太祖的称呼，赵匡胤当时尚未称帝。", "phases": [], "location_name": "后周朝廷至秦凤军前", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "deb32f52-9d04-5c6c-9dc0-f4e179989e87"}]'::jsonb)
