INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "柴荣下令停废没有朝廷敕赐名额的寺院。《旧五代史》所载诏令还规定，将佛像和僧尼迁入保留的寺院；无敕额寺院的县城、军镇等另有留设例外，不能理解为所有寺院一律拆毁。", "citation": "卷292·显德二年（955年五月至七月及相关追述）·zztj-v292-y0955-p017·原文件第49行", "note": "原文：敕天下寺院，非敕额者悉废之。；核对说明：停废是行政处置，不直接等于所有建筑均已拆毁；详细例外由独立诏令引用说明。", "status": "draft", "id": "5433fecd-8b17-541b-ac73-8e71fbcdc2da", "subject_id": "b394f5cf-01d1-5d50-a6a0-f86a72868875", "source_id": "b9e28c71-de1a-56b8-b958-f61e46078893"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "955年五月，具体日据《旧五代史》记为甲戌", "citation": "卷292·显德二年（955年五月至七月及相关追述）·zztj-v292-y0955-p017·原文件第49行", "note": "原文：敕天下寺院，非敕额者悉废之。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "470e3547-b153-5bd4-b4d7-c1a6367dce6d", "subject_id": "b394f5cf-01d1-5d50-a6a0-f86a72868875", "source_id": "b9e28c71-de1a-56b8-b958-f61e46078893"}, {"subject_table": "person", "field_path": "description", "claim_text": "柴荣：下令整顿寺院。", "citation": "卷292·显德二年（955年五月至七月及相关追述）·zztj-v292-y0955-p017·原文件第49行", "note": "原文：敕天下寺院，非敕额者悉废之。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "c52fd34e-cbfc-5958-a8dc-5d719afa2140", "subject_id": "697c1a4f-b373-5a78-8b47-330fe349a424", "source_id": "b9e28c71-de1a-56b8-b958-f61e46078893"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "柴荣：下令整顿寺院。", "citation": "卷292·显德二年（955年五月至七月及相关追述）·zztj-v292-y0955-p017·原文件第49行", "note": "原文：敕天下寺院，非敕额者悉废之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "55a477a4-88fe-50e6-8754-2121695266ef", "subject_id": "33ec9f8f-a612-5e00-a03e-447ea8a0d897", "source_id": "b9e28c71-de1a-56b8-b958-f61e46078893"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "《旧五代史》将整顿寺院诏令系于五月甲戌。", "citation": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002728；EPUB电子本，纸本及异文待核", "note": "原文：甲戌，詔曰：；核对说明：月份根据同段开头五月辛未核对，甲戌是诏令日，不是全年清点统计日。", "status": "draft", "id": "162607d2-2d36-5a28-96ee-e7c835e355ee", "subject_id": "b394f5cf-01d1-5d50-a6a0-f86a72868875", "source_id": "7eabd0e7-101c-523a-9c6c-1f5536a53440"}, {"subject_table": "event", "field_path": "description", "claim_text": "诏令以整顿僧尼违法和寺院管理为理由，宣称目的是维护教法。", "citation": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002729；EPUB电子本，纸本及异文待核", "note": "原文：將隆教法，須辨否臧，宜舉舊章，用革前弊。；核对说明：这是诏令对政策目的的陈述，不据此认定所有停废寺院都有犯罪。", "status": "draft", "id": "d1775df8-4337-5311-a16c-934d5ddd8839", "subject_id": "b394f5cf-01d1-5d50-a6a0-f86a72868875", "source_id": "2da1209c-584a-5a88-b944-11af0a3b33eb"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》记停废寺院的佛像及僧尼须迁入保留寺院安置。", "citation": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002730；EPUB电子本，纸本及异文待核", "note": "原文：其無敕額者，並仰停廢，所有功德佛像及僧尼，並騰並於合留寺院內安置。；核对说明：区分寺院停废、人员迁并和建筑拆毁，未记所有僧尼一律还俗。", "status": "draft", "id": "83d1a6d8-2d2b-51c3-b07b-a659a42a05b4", "subject_id": "b394f5cf-01d1-5d50-a6a0-f86a72868875", "source_id": "08451b3c-5485-5cb3-bc6a-4557956947bd"}, {"subject_table": "event", "field_path": "description", "claim_text": "无敕额寺院的县城可在原定停废寺院中按条件留设僧寺、尼寺；军镇坊郭和二百户以上聚落按同类规则办理，边远州郡另有各留两所的规定。", "citation": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002730；EPUB电子本，纸本及异文待核", "note": "原文：天下諸縣城郭內，若無敕額寺院，只於合停廢寺院內，選功德屋宇最多者，或寺院僧尼各留一所，若無尼住，只留僧寺院一所。諸軍鎮坊郭及二百戶已上者，亦依諸縣例指揮。如邊遠州郡無敕額寺院處，於停廢寺院內僧尼各留兩所。；核对说明：保留诏令例外与数量，不把《资治通鉴》简述解释为毫无例外的建筑清零。", "status": "draft", "id": "53ed6ebf-0567-5771-841c-95f3422720db", "subject_id": "b394f5cf-01d1-5d50-a6a0-f86a72868875", "source_id": "08451b3c-5485-5cb3-bc6a-4557956947bd"}, {"subject_table": "event", "field_path": "description", "claim_text": "诏令还禁止新建寺院，并禁止王公、外戚及地方长官申请新建寺院和开置戒坛。", "citation": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002730；EPUB电子本，纸本及异文待核", "note": "原文：今後並不得創造寺院蘭若。王公戚裏諸道節刺已下，今後不得奏請創造寺院及請開置戒壇。；核对说明：新建禁令与既有寺院停废分别说明。", "status": "draft", "id": "f1c653a7-f8e2-5751-8e06-3931a8d94be1", "subject_id": "b394f5cf-01d1-5d50-a6a0-f86a72868875", "source_id": "08451b3c-5485-5cb3-bc6a-4557956947bd"}, {"subject_table": "event", "field_path": "description", "claim_text": "柴荣禁止未经许可剃度僧尼，要求有意出家者先取得家人同意。《旧五代史》详记按父母祖父母、已孤者同居伯叔兄等情况处理，并设年龄、经文考核和奉养家人等条件。", "citation": "卷292·显德二年（955年五月至七月及相关追述）·zztj-v292-y0955-p017·原文件第49行", "note": "原文：禁私度僧尼，凡欲出家者必俟祖父母、父母、伯叔之命。；核对说明：按原文动作分录；不外推原因与结果。", "status": "draft", "id": "f61ad3b1-c5b7-524a-86d8-e317b65ad28e", "subject_id": "d7968416-545a-522d-ba33-47d3e780d04b", "source_id": "b9e28c71-de1a-56b8-b958-f61e46078893"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "955年五月寺院整顿诏令", "citation": "卷292·显德二年（955年五月至七月及相关追述）·zztj-v292-y0955-p017·原文件第49行", "note": "原文：禁私度僧尼，凡欲出家者必俟祖父母、父母、伯叔之命。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "e052bf1b-eda2-5fff-99c9-32e04ccff86b", "subject_id": "d7968416-545a-522d-ba33-47d3e780d04b", "source_id": "b9e28c71-de1a-56b8-b958-f61e46078893"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "柴荣：规定出家许可条件并禁止私自剃度。", "citation": "卷292·显德二年（955年五月至七月及相关追述）·zztj-v292-y0955-p017·原文件第49行", "note": "原文：禁私度僧尼，凡欲出家者必俟祖父母、父母、伯叔之命。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "fc14439f-5b87-584d-8dc4-b29e6687f27b", "subject_id": "46fd1fb3-812e-522f-85c1-6900081a14b9", "source_id": "b9e28c71-de1a-56b8-b958-f61e46078893"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》详记家庭许可条件：须获父母、祖父母同意，已孤者取同居伯叔兄许可。", "citation": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002730；EPUB电子本，纸本及异文待核", "note": "原文：男子女子如有誌願出家者，並取父母、祖父母處分，已孤者取同居伯叔兄處分，候聽許方得出家。；核对说明：按家庭情形分列，不译为所有亲属同时同意。", "status": "draft", "id": "c3ac2cdf-f5e0-54c0-99ff-8853abf5c09c", "subject_id": "d7968416-545a-522d-ba33-47d3e780d04b", "source_id": "08451b3c-5485-5cb3-bc6a-4557956947bd"}, {"subject_table": "event", "field_path": "description", "claim_text": "诏令规定男性十五岁以上、女性十三岁以上，并须通过经文考核和官府申请程序。", "citation": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002730；EPUB电子本，纸本及异文待核", "note": "原文：男年十五已上，念得經文一百紙，或讀得經文五百紙，女年十三已上，念得經文七十紙，或讀得經文三百紙者，經本府陳狀乞剃頭，委錄事參軍本判官試驗經文。；核对说明：纸为底本经文计量，不换算成现代页数；考核背诵和阅读标准分别保留。", "status": "draft", "id": "ebecc9ff-fc5f-5798-94f8-82b6d9313f5d", "subject_id": "d7968416-545a-522d-ba33-47d3e780d04b", "source_id": "08451b3c-5485-5cb3-bc6a-4557956947bd"}, {"subject_table": "event", "field_path": "description", "claim_text": "家中有父母祖父母在世而无其他子女侍养者，不准出家。", "citation": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002730；EPUB电子本，纸本及异文待核", "note": "原文：應男女有父母、祖父母在，別無兒息侍養，不聽出家。；核对说明：体现赡养条件，不据诏令推定每一僧尼的具体家庭情况。", "status": "draft", "id": "723f8460-5714-512b-b2da-33692d68eb1b", "subject_id": "d7968416-545a-522d-ba33-47d3e780d04b", "source_id": "08451b3c-5485-5cb3-bc6a-4557956947bd"}, {"subject_table": "event", "field_path": "description", "claim_text": "柴荣限定两京等地可以设置戒坛。", "citation": "卷292·显德二年（955年五月至七月及相关追述）·zztj-v292-y0955-p017·原文件第49行", "note": "原文：惟两京、大名府、京兆府、青州听设戒坛。；核对说明：两京沿史载名称，不给未经核实的现代坐标。", "status": "draft", "id": "2958fbf1-39e5-56dc-b388-1c47ca93b719", "subject_id": "97f1daa7-05e2-58bb-9d16-a8e72e3da2e6", "source_id": "b9e28c71-de1a-56b8-b958-f61e46078893"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "955年五月寺院整顿诏令", "citation": "卷292·显德二年（955年五月至七月及相关追述）·zztj-v292-y0955-p017·原文件第49行", "note": "原文：惟两京、大名府、京兆府、青州听设戒坛。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "5d3cd80e-fbcc-5927-8ed3-120dc84868db", "subject_id": "97f1daa7-05e2-58bb-9d16-a8e72e3da2e6", "source_id": "b9e28c71-de1a-56b8-b958-f61e46078893"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "柴荣：限定受戒地点。", "citation": "卷292·显德二年（955年五月至七月及相关追述）·zztj-v292-y0955-p017·原文件第49行", "note": "原文：惟两京、大名府、京兆府、青州听设戒坛。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "3db1d2c4-1bc8-55da-a20e-63b77f9b94b5", "subject_id": "e5fe0a4c-9da2-559c-9a43-fe63676f31ff", "source_id": "b9e28c71-de1a-56b8-b958-f61e46078893"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》同时说明两京由祠部差官引试，其他三处由当地判官、录事参军考核。", "citation": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002730；EPUB电子本，纸本及异文待核", "note": "原文：兩京、大名府、京兆府、青州各處置戒壇，候受戒時，兩京委祠部差官引試，其大名府等三處，只委本判官錄事參軍引試。；核对说明：这是受戒管理规则，不虚构各地实际受戒人数。", "status": "draft", "id": "5a9f3a45-d68a-5387-8d4e-603d6227ea9d", "subject_id": "97f1daa7-05e2-58bb-9d16-a8e72e3da2e6", "source_id": "08451b3c-5485-5cb3-bc6a-4557956947bd"}, {"subject_table": "event", "field_path": "description", "claim_text": "柴荣禁止僧俗以舍身、断手足、炼指、挂灯、带钳等方式聚众惑众。这里记录诏令及其对这些行为的判断，未据此认定所有宗教活动都属欺骗。", "citation": "卷292·显德二年（955年五月至七月及相关追述）·zztj-v292-y0955-p017·原文件第49行", "note": "原文：禁僧俗舍身、断手足、炼指、挂灯、带钳之类幻惑流俗者。；核对说明：按原文动作分录；不外推原因与结果。", "status": "draft", "id": "ac7d0edf-3327-5b97-bb55-c963f1d22960", "subject_id": "8f422b4b-d5b7-5be4-baf6-4fc78881ec30", "source_id": "b9e28c71-de1a-56b8-b958-f61e46078893"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "955年五月寺院整顿诏令", "citation": "卷292·显德二年（955年五月至七月及相关追述）·zztj-v292-y0955-p017·原文件第49行", "note": "原文：禁僧俗舍身、断手足、炼指、挂灯、带钳之类幻惑流俗者。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "88dbdcab-9fa2-5188-86bf-e053d9d28f74", "subject_id": "8f422b4b-d5b7-5be4-baf6-4fc78881ec30", "source_id": "b9e28c71-de1a-56b8-b958-f61e46078893"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "柴荣：禁止以自伤等行为聚众惑众。", "citation": "卷292·显德二年（955年五月至七月及相关追述）·zztj-v292-y0955-p017·原文件第49行", "note": "原文：禁僧俗舍身、断手足、炼指、挂灯、带钳之类幻惑流俗者。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "0128fd72-e027-5352-b4f2-0ee51fc46a3c", "subject_id": "3e4bd4f1-bbf5-5a8f-b202-d8ff3b93081d", "source_id": "b9e28c71-de1a-56b8-b958-f61e46078893"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》所载诏令还规定相关处罚，包括发配边远、勒令还俗，罪重者依律处置。", "citation": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002731；EPUB电子本，纸本及异文待核", "note": "原文：今後一切止絕。如有此色人，仰所在嚴斷，遞配邊遠，仍勒歸俗，其所犯罪重者，準格律處分。；核对说明：这是处罚规定，不当作已有全部施行的具名案件。", "status": "draft", "id": "c3241e9b-127e-57c7-becd-6125b252c129", "subject_id": "8f422b4b-d5b7-5be4-baf6-4fc78881ec30", "source_id": "ff64903e-32fa-5c7c-9e9e-54a75562bc2b"}, {"subject_table": "event", "field_path": "description", "claim_text": "柴荣要求每年编造僧尼名册，及时登记死亡和还俗。", "citation": "卷292·显德二年（955年五月至七月及相关追述）·zztj-v292-y0955-p017·原文件第49行", "note": "原文：令两京及诸州每岁造僧帐，有死亡、归俗，皆随时开落。；核对说明：每岁是制度周期，不能把未来各年编册当作955年已逐次完成。", "status": "draft", "id": "54113390-068c-54fa-8751-f4dead7fd962", "subject_id": "922c5bed-ac75-5ddb-893e-65ee402c27ce", "source_id": "b9e28c71-de1a-56b8-b958-f61e46078893"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "955年五月诏令规定此后每年办理", "citation": "卷292·显德二年（955年五月至七月及相关追述）·zztj-v292-y0955-p017·原文件第49行", "note": "原文：令两京及诸州每岁造僧帐，有死亡、归俗，皆随时开落。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "9b387261-3a55-55b2-848a-a50f9c070838", "subject_id": "922c5bed-ac75-5ddb-893e-65ee402c27ce", "source_id": "b9e28c71-de1a-56b8-b958-f61e46078893"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "柴荣：要求建立并更新僧尼名册。", "citation": "卷292·显德二年（955年五月至七月及相关追述）·zztj-v292-y0955-p017·原文件第49行", "note": "原文：令两京及诸州每岁造僧帐，有死亡、归俗，皆随时开落。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "82430503-82eb-5be0-b72d-4a5976b3362c", "subject_id": "4035499a-86fb-55ce-a5b6-386d68d08275", "source_id": "b9e28c71-de1a-56b8-b958-f61e46078893"}, {"subject_table": "event", "field_path": "description", "claim_text": "名册每年造两份，一份奏报，一份送祠部；县自四月十五日后上报，州汇总后须在五月底前送京，未列名者勒令还俗。", "citation": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002731；EPUB电子本，纸本及异文待核", "note": "原文：每年造僧帳兩本，其一本奏聞，一本申祠部，逐年四月十五日後，勒諸縣取索管界寺院僧尼數目申州，州司攢帳，至五月終已前文帳到京，僧尼籍帳內無名者，並勒還俗。；核对说明：这是按年执行的规定，不将首次诏令前的四月十五日当作当年已执行的确日。", "status": "draft", "id": "78ad8f2f-2e64-5ed9-9d0f-1999687f881f", "subject_id": "922c5bed-ac75-5ddb-893e-65ee402c27ce", "source_id": "ff64903e-32fa-5c7c-9e9e-54a75562bc2b"}, {"subject_table": "event", "field_path": "description", "claim_text": "《通鉴》记955年保留寺院2694所，停废30336所，登记僧人42444名、尼僧18756名。《旧五代史》记寺院两项数量相同，僧尼登记合计61200人。这些是史书记载的当年汇总，不是五月诏令颁布当天的实测数字。", "citation": "卷292